### 3. PERMISSIONS SYSTEM: API SURFACE & CONSTANTS

**Master file:** `C:/Users/olive_/OneDrive/Documentos/codigo/Momma/momma-stock-insight/src/shared/hooks/usePermissions.tsx`

**Core API:**
```typescript
interface PermissionsContextType {
  permissions: Permission[];        // array of {permission_name, permission_display_name, module}
  userRole: UserRole | null;        // {role_name, role_display_name, can_change_store}
  loading: boolean;

  // Main predicates:
  hasPermission: (permissionName: string) => boolean;
  hasAnyPermission: (permissionNames: string[]) => boolean;
  isAdmin: () => boolean;           // Detects 'admin'/'administrador'/'administrator' role
  canAccessModule: (module: string) => boolean;

  // Specific shortcuts:
  canViewFinanceiro: () => boolean;
  canViewDashboard: () => boolean;
  canSwitchStore: () => boolean;
  canSelectStoreNF: () => boolean;
  // ... etc
}

const { hasPermission, isAdmin, canAccessModule } = usePermissions();
```

**Permission detection logic:**
```typescript
const isAdmin = (): boolean => {
  const roleName = userRole?.role_name?.toLowerCase();
  const adminAliases = ['admin', 'administrador', 'administrator'];
  return roleName ? adminAliases.includes(roleName) : false;
};

const hasPermission = (permissionName: string): boolean => {
  return permissions.some(p => p.permission_name === permissionName);
};
```

**Feature-specific permission helpers** (see `src/features/funcionarios/lib/permissions.ts`):
```typescript
export function useIsRhMaster(): boolean {
  const { isAdmin, hasPermission } = usePermissions();
  return isAdmin() || hasPermission('view_funcionarios_dashboard');
}

export function useCanEditFuncionarios(): boolean {
  const { isAdmin, hasPermission } = usePermissions();
  return isAdmin() || hasPermission('edit_funcionarios');
}
```

**For OUVIDORIA (OWNERS/DONAS ONLY):**
Create `src/features/ouvidoria/lib/permissions.ts`:
```typescript
export function useCanViewOuvidoria(): boolean {
  const { isAdmin, hasPermission } = usePermissions();
  return isAdmin() || hasPermission('view_ouvidoria');
}

export function useCanRespondOuvidoria(): boolean {
  const { isAdmin, hasPermission } = usePermissions();
  return isAdmin() || hasPermission('manage_ouvidoria');
}
```

**Permission string to declare in DB:**
- `view_ouvidoria` — read complaints (owners/management)
- `manage_ouvidoria` — respond to & close complaints

