### 6. SAMPLE PAGE COMPONENT STRUCTURE

**Reference:** `C:/Users/olive_/OneDrive/Documentos/codigo/Momma/momma-stock-insight/src/features/funcionarios/ui/Funcionarios.page.tsx` (head)

```typescript
import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Filter, Plus } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { TelemetryErrorBoundary } from '@/shared/ui/TelemetryErrorBoundary';
import { useStore } from '@/shared/contexts/StoreContext';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useEmployees } from '../model/useEmployees';    // Data hook
import { useCanEditFuncionarios } from '../lib/permissions'; // Permission gate

export default function FuncionariosPage() {
  return (
    <TelemetryErrorBoundary moduleName="funcionarios">
      <FuncionariosPageInner />
    </TelemetryErrorBoundary>
  );
}

function FuncionariosPageInner() {
  const navigate = useNavigate();
  const { selectedStore } = useStore();
  const { isAdmin } = usePermissions();
  const canEdit = useCanEditFuncionarios();
  const { data: employees, loading, error } = useEmployees(selectedStore?.id);

  return (
    <MommaPageLayout
      title="Funcionários"
      description="Gestão de equipe"
      actionButton={
        canEdit && (
          <Button onClick={() => navigate('/funcionarios/novo')}>
            <Plus className="mr-2 h-4 w-4" />
            Novo Funcionário
          </Button>
        )
      }
    >
      {/* Content */}
    </MommaPageLayout>
  );
}
```

**For Ouvidoria.page.tsx pattern:**
```typescript
import { TelemetryErrorBoundary } from '@/shared/ui/TelemetryErrorBoundary';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { useStore } from '@/shared/contexts/StoreContext';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useCanViewOuvidoria, useCanRespondOuvidoria } from '../lib/permissions';
import { useOuvidoriaList } from '../model/useOuvidoriaList';

export default function OuvidoriaPage() {
  return (
    <TelemetryErrorBoundary moduleName="ouvidoria">
      <OuvidoriaPageInner />
    </TelemetryErrorBoundary>
  );
}

function OuvidoriaPageInner() {
  const { selectedStore } = useStore();
  const canViewOuvidoria = useCanViewOuvidoria();
  const canRespond = useCanRespondOuvidoria();
  const { data: complaints, loading } = useOuvidoriaList(selectedStore?.id);

  if (!canViewOuvidoria) {
    return <div>Acesso restrito a proprietários.</div>;
  }

  return (
    <MommaPageLayout
      title="Ouvidoria"
      description="Canal anônimo de denúncias e sugestões"
    >
      {/* List + Detail views */}
    </MommaPageLayout>
  );
}
```

