input.query:
-- OUVIDORIA ANÔNIMA — Canal de Denúncias Seguro (v1)
-- INVARIANTE DE ANONIMATO: nenhuma tabela armazena user_id/auth.uid()/IP/user-agent/
-- created_by. As 3 RPCs públicas nunca chamam auth.uid(). Insert via SECURITY DEFINER.
-- Acesso de leitura restrito às donas via allowlist ouvidoria_acesso + can_view_ouvidoria().

-- 1) Tabela principal de denúncias
CREATE TABLE IF NOT EXISTS public.ouvidoria_denuncias (
  id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  protocolo           text        UNIQUE NOT NULL,
  senha_hash          text        NOT NULL,
  categoria           text        NOT NULL
                                  CHECK (categoria IN (
                                    'assedio_moral','assedio_sexual','fraude_financeiro','discriminacao',
                                    'seguranca_trabalho','conduta_etica','sugestao','outro')),
  loja_id             integer     NULL REFERENCES public.lojas(id) ON DELETE SET NULL,
  mensagem            text        NOT NULL,
  status              text        NOT NULL DEFAULT 'recebida'
                                  CHECK (status IN ('recebida','em_analise','resolvida','arquivada')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  ultima_resposta_em  timestamptz NULL
);

COMMENT ON TABLE public.ouvidoria_denuncias IS
'Canal de ouvidoria anônima. INVARIANTE: nenhuma linha contém user_id, auth.uid(), IP, user-agent ou qualquer identificador do remetente. Inserção exclusiva via RPC criar_denuncia_ouvidoria (SECURITY DEFINER). Acesso de leitura restrito às donas via can_view_ouvidoria().';

CREATE INDEX IF NOT EXISTS idx_ouvidoria_denuncias_status ON public.ouvidoria_denuncias (status);
CREATE INDEX IF NOT EXISTS idx_ouvidoria_denuncias_created_at ON public.ouvidoria_denuncias (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ouvidoria_denuncias_loja_id ON public.ouvidoria_denuncias (loja_id);

-- 2) Thread de mensagens mão-dupla
CREATE TABLE IF NOT EXISTS public.ouvidoria_mensagens (
  id                    uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  denuncia_id           uuid        NOT NULL REFERENCES public.ouvidoria_denuncias(id) ON DELETE CASCADE,
  autor                 text        NOT NULL CHECK (autor IN ('denunciante','ouvidoria')),
  mensagem              text        NOT NULL,
  respondido_por        uuid        NULL REFERENCES auth.users(id) ON DELETE SET NULL,
  lida_pela_ouvidoria   boolean     NOT NULL DEFAULT false,
  created_at            timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.ouvidoria_mensagens IS
'Thread de mensagens da ouvidoria. autor=denunciante: anônimo (sem user_id). autor=ouvidoria: respondido_por identifica a dona internamente mas NUNCA é exposto nas RPCs públicas.';
COMMENT ON COLUMN public.ouvidoria_mensagens.respondido_por IS
'Identidade da dona que respondeu. Uso EXCLUSIVAMENTE interno. Nunca retornado pelas RPCs públicas anônimas.';

CREATE INDEX IF NOT EXISTS idx_ouvidoria_mensagens_denuncia_created ON public.ouvidoria_mensagens (denuncia_id, created_at);
CREATE INDEX IF NOT EXISTS idx_ouvidoria_mensagens_nao_lidas ON public.ouvidoria_mensagens (denuncia_id)
  WHERE autor = 'denunciante' AND lida_pela_ouvidoria = false;

-- 3) Allowlist de acesso das donas
CREATE TABLE IF NOT EXISTS public.ouvidoria_acesso (
  user_id     uuid        PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  observacao  text        NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.ouvidoria_acesso IS
'Allowlist das pessoas autorizadas a ler e gerenciar denúncias da ouvidoria. Seed manual via SQL pelo CTO. Nenhuma interface self-service.';

-- 4) Helper de autorização
CREATE OR REPLACE FUNCTION public.can_view_ouvidoria(p_user uuid DEFAULT auth.uid())
RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.ouvidoria_acesso WHERE user_id = p_user);
$$;
COMMENT ON FUNCTION public.can_view_ouvidoria(uuid) IS
'Retorna true se o user está na allowlist ouvidoria_acesso. NÃO herda de is_admin_user() por design.';
REVOKE ALL ON FUNCTION public.can_view_ouvidoria(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_view_ouvidoria(uuid) TO authenticated, service_role;

-- 5) RPC pública: criar_denuncia_ouvidoria
CREATE OR REPLACE FUNCTION public.criar_denuncia_ouvidoria(
  p_categoria text, p_loja_id integer, p_mensagem text, p_senha text
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_categorias_validas text[] := ARRAY['assedio_moral','assedio_sexual','fraude_financeiro','discriminacao','seguranca_trabalho','conduta_etica','sugestao','outro'];
  v_protocolo  text;
  v_senha_hash text;
  i integer;
BEGIN
  IF p_categoria IS NULL OR NOT (p_categoria = ANY(v_categorias_validas)) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Categoria inválida.');
  END IF;
  IF p_mensagem IS NULL OR length(trim(p_mensagem)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem não pode ser vazia.');
  END IF;
  IF length(p_mensagem) > 5000 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem excede 5000 caracteres.');
  END IF;
  IF p_senha IS NULL OR length(p_senha) < 4 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Senha deve ter pelo menos 4 caracteres.');
  END IF;
  v_protocolo := NULL;
  FOR i IN 1..10 LOOP
    v_protocolo := 'OUV-' || upper(encode(extensions.gen_random_bytes(5), 'hex'));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.ouvidoria_denuncias WHERE protocolo = v_protocolo);
    v_protocolo := NULL;
  END LOOP;
  IF v_protocolo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Não foi possível gerar protocolo único. Tente novamente.');
  END IF;
  v_senha_hash := extensions.crypt(p_senha, extensions.gen_salt('bf'));
  INSERT INTO public.ouvidoria_denuncias (protocolo, senha_hash, categoria, loja_id, mensagem)
  VALUES (v_protocolo, v_senha_hash, p_categoria, p_loja_id, trim(p_mensagem));
  RETURN jsonb_build_object('ok', true, 'protocolo', v_protocolo);
END;
$$;
COMMENT ON FUNCTION public.criar_denuncia_ouvidoria(text, integer, text, text) IS
'Cria uma denúncia anônima. NUNCA chama auth.uid(). Concedida a anon+authenticated.';
REVOKE ALL ON FUNCTION public.criar_denuncia_ouvidoria(text, integer, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.criar_denuncia_ouvidoria(text, integer, text, text) TO anon, authenticated, service_role;

-- 6) RPC pública: consultar_protocolo_ouvidoria
CREATE OR REPLACE FUNCTION public.consultar_protocolo_ouvidoria(p_protocolo text, p_senha text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_rec record;
  v_senha_ok boolean;
  v_mensagens jsonb;
BEGIN
  SELECT id, protocolo, senha_hash, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em
  INTO v_rec FROM public.ouvidoria_denuncias WHERE protocolo = p_protocolo;
  IF NOT FOUND THEN
    PERFORM extensions.crypt(p_senha, extensions.gen_salt('bf'));
    RETURN jsonb_build_object('ok', false);
  END IF;
  v_senha_ok := (extensions.crypt(p_senha, v_rec.senha_hash) = v_rec.senha_hash);
  IF NOT v_senha_ok THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('autor', m.autor, 'mensagem', m.mensagem, 'created_at', m.created_at) ORDER BY m.created_at), '[]'::jsonb)
  INTO v_mensagens FROM public.ouvidoria_mensagens m WHERE m.denuncia_id = v_rec.id;
  RETURN jsonb_build_object(
    'ok', true,
    'denuncia', jsonb_build_object(
      'protocolo', v_rec.protocolo, 'categoria', v_rec.categoria, 'loja_id', v_rec.loja_id,
      'mensagem', v_rec.mensagem, 'status', v_rec.status, 'created_at', v_rec.created_at,
      'updated_at', v_rec.updated_at, 'ultima_resposta_em', v_rec.ultima_resposta_em),
    'mensagens', v_mensagens);
END;
$$;
COMMENT ON FUNCTION public.consultar_protocolo_ouvidoria(text, text) IS
'Consulta denúncia por protocolo+senha. NUNCA chama auth.uid(). Falha genérica. Retorna colunas explícitas — sem senha_hash e sem respondido_por.';
REVOKE ALL ON FUNCTION public.consultar_protocolo_ouvidoria(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.consultar_protocolo_ouvidoria(text, text) TO anon, authenticated, service_role;

-- 7) RPC pública: responder_protocolo_ouvidoria
CREATE OR REPLACE FUNCTION public.responder_protocolo_ouvidoria(p_protocolo text, p_senha text, p_mensagem text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_rec record;
  v_senha_ok boolean;
BEGIN
  IF p_mensagem IS NULL OR length(trim(p_mensagem)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem não pode ser vazia.');
  END IF;
  IF length(p_mensagem) > 5000 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem excede 5000 caracteres.');
  END IF;
  SELECT id, senha_hash INTO v_rec FROM public.ouvidoria_denuncias WHERE protocolo = p_protocolo;
  IF NOT FOUND THEN
    PERFORM extensions.crypt(p_senha, extensions.gen_salt('bf'));
    RETURN jsonb_build_object('ok', false);
  END IF;
  v_senha_ok := (extensions.crypt(p_senha, v_rec.senha_hash) = v_rec.senha_hash);
  IF NOT v_senha_ok THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  INSERT INTO public.ouvidoria_mensagens (denuncia_id, autor, mensagem, lida_pela_ouvidoria)
  VALUES (v_rec.id, 'denunciante', trim(p_mensagem), false);
  UPDATE public.ouvidoria_denuncias SET updated_at = now() WHERE id = v_rec.id;
  RETURN jsonb_build_object('ok', true);
END;
$$;
COMMENT ON FUNCTION public.responder_protocolo_ouvidoria(text, text, text) IS
'Denunciante adiciona mensagem ao thread via protocolo+senha. NUNCA chama auth.uid().';
REVOKE ALL ON FUNCTION public.responder_protocolo_ouvidoria(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.responder_protocolo_ouvidoria(text, text, text) TO anon, authenticated, service_role;

-- 8) RPC autenticada: responder_ouvidoria (donas)
CREATE OR REPLACE FUNCTION public.responder_ouvidoria(p_denuncia_id uuid, p_mensagem text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.can_view_ouvidoria() THEN
    RAISE EXCEPTION 'Sem permissão para acessar a ouvidoria' USING ERRCODE = '42501';
  END IF;
  IF p_mensagem IS NULL OR length(trim(p_mensagem)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem não pode ser vazia.');
  END IF;
  IF length(p_mensagem) > 5000 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem excede 5000 caracteres.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ouvidoria_denuncias WHERE id = p_denuncia_id) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Denúncia não encontrada.');
  END IF;
  INSERT INTO public.ouvidoria_mensagens (denuncia_id, autor, mensagem, respondido_por, lida_pela_ouvidoria)
  VALUES (p_denuncia_id, 'ouvidoria', trim(p_mensagem), auth.uid(), true);
  UPDATE public.ouvidoria_denuncias SET updated_at = now(), ultima_resposta_em = now() WHERE id = p_denuncia_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;
COMMENT ON FUNCTION public.responder_ouvidoria(uuid, text) IS
'Dona responde ao denunciante. Requer can_view_ouvidoria(). respondido_por=auth.uid() interno — nunca exposto.';
REVOKE ALL ON FUNCTION public.responder_ouvidoria(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.responder_ouvidoria(uuid, text) TO authenticated, service_role;

-- 9) RPC autenticada: atualizar_status_ouvidoria (donas)
CREATE OR REPLACE FUNCTION public.atualizar_status_ouvidoria(p_denuncia_id uuid, p_status text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_status_validos text[] := ARRAY['recebida','em_analise','resolvida','arquivada'];
BEGIN
  IF NOT public.can_view_ouvidoria() THEN
    RAISE EXCEPTION 'Sem permissão para acessar a ouvidoria' USING ERRCODE = '42501';
  END IF;
  IF p_status IS NULL OR NOT (p_status = ANY(v_status_validos)) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Status inválido.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ouvidoria_denuncias WHERE id = p_denuncia_id) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Denúncia não encontrada.');
  END IF;
  UPDATE public.ouvidoria_denuncias SET status = p_status, updated_at = now() WHERE id = p_denuncia_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;
COMMENT ON FUNCTION public.atualizar_status_ouvidoria(uuid, text) IS
'Dona altera status da denúncia. Requer can_view_ouvidoria(). Valida enum de status.';
REVOKE ALL ON FUNCTION public.atualizar_status_ouvidoria(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.atualizar_status_ouvidoria(uuid, text) TO authenticated, service_role;

-- 10) RPC autenticada: marcar_ouvidoria_lida (donas)
CREATE OR REPLACE FUNCTION public.marcar_ouvidoria_lida(p_denuncia_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.can_view_ouvidoria() THEN
    RAISE EXCEPTION 'Sem permissão para acessar a ouvidoria' USING ERRCODE = '42501';
  END IF;
  UPDATE public.ouvidoria_mensagens SET lida_pela_ouvidoria = true
  WHERE denuncia_id = p_denuncia_id AND autor = 'denunciante' AND lida_pela_ouvidoria = false;
END;
$$;
COMMENT ON FUNCTION public.marcar_ouvidoria_lida(uuid) IS
'Dona marca como lidas as mensagens do denunciante de uma denúncia. Zera badge realtime.';
REVOKE ALL ON FUNCTION public.marcar_ouvidoria_lida(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.marcar_ouvidoria_lida(uuid) TO authenticated, service_role;

-- 11) RLS
ALTER TABLE public.ouvidoria_denuncias ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS ouvidoria_denuncias_select_donas ON public.ouvidoria_denuncias;
CREATE POLICY ouvidoria_denuncias_select_donas ON public.ouvidoria_denuncias
  FOR SELECT TO authenticated USING (public.can_view_ouvidoria((SELECT auth.uid())));
DROP POLICY IF EXISTS ouvidoria_denuncias_service ON public.ouvidoria_denuncias;
CREATE POLICY ouvidoria_denuncias_service ON public.ouvidoria_denuncias
  FOR ALL TO service_role USING (true) WITH CHECK (true);

ALTER TABLE public.ouvidoria_mensagens ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS ouvidoria_mensagens_select_donas ON public.ouvidoria_mensagens;
CREATE POLICY ouvidoria_mensagens_select_donas ON public.ouvidoria_mensagens
  FOR SELECT TO authenticated USING (public.can_view_ouvidoria((SELECT auth.uid())));
DROP POLICY IF EXISTS ouvidoria_mensagens_service ON public.ouvidoria_mensagens;
CREATE POLICY ouvidoria_mensagens_service ON public.ouvidoria_mensagens
  FOR ALL TO service_role USING (true) WITH CHECK (true);

ALTER TABLE public.ouvidoria_acesso ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS ouvidoria_acesso_select_donas ON public.ouvidoria_acesso;
CREATE POLICY ouvidoria_acesso_select_donas ON public.ouvidoria_acesso
  FOR SELECT TO authenticated USING (public.can_view_ouvidoria((SELECT auth.uid())));
DROP POLICY IF EXISTS ouvidoria_acesso_service ON public.ouvidoria_acesso;
CREATE POLICY ouvidoria_acesso_service ON public.ouvidoria_acesso
  FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 12) Realtime — apenas ouvidoria_mensagens
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND tablename = 'ouvidoria_mensagens'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.ouvidoria_mensagens;
  END IF;
END;
$$;

