-- Correção de hardening: remover o EXECUTE que o DEFAULT PRIVILEGES do Supabase
-- concede a anon nas funções restritas às donas (o REVOKE FROM PUBLIC não cobre o grant direto a anon).
REVOKE EXECUTE ON FUNCTION public.can_view_ouvidoria(uuid) FROM anon;
REVOKE EXECUTE ON FUNCTION public.responder_ouvidoria(uuid, text) FROM anon;
REVOKE EXECUTE ON FUNCTION public.atualizar_status_ouvidoria(uuid, text) FROM anon;
REVOKE EXECUTE ON FUNCTION public.marcar_ouvidoria_lida(uuid) FROM anon;

-- Verificação: anon NÃO deve mais aparecer no ACL das 4 funções das donas;
-- deve permanecer nas 3 públicas (criar/consultar/responder_protocolo).
select
  p.proname,
  (array_to_string(p.proacl, ' ') like '%anon=X%') as anon_pode_executar
from pg_proc p
join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.proname like '%ouvidoria%'
order by p.proname;

