-- A1 (criar) + A4 (consultar certo/errado) numa tacada
select
  p.protocolo,
  (public.consultar_protocolo_ouvidoria(p.protocolo, 'senha123'))->>'ok'  as consulta_senha_certa,
  (public.consultar_protocolo_ouvidoria(p.protocolo, 'senha_errada'))->>'ok' as consulta_senha_errada,
  (public.consultar_protocolo_ouvidoria('OUV-INEXISTENTE', 'qualquer'))->>'ok' as consulta_protocolo_inexistente
from (
  select (public.criar_denuncia_ouvidoria('assedio_moral', 2, 'Teste anonimo A1 — verificar ausencia de identidade', 'senha123'))->>'protocolo' as protocolo
) p;

-- A1: confirmar que a linha inserida NÃO tem nenhuma coluna de identidade (lista de colunas da tabela)
select string_agg(column_name, ', ' order by ordinal_position) as colunas_da_tabela
from information_schema.columns
where table_schema='public' and table_name='ouvidoria_denuncias';

-- A4: consulta certo/errado/inexistente (resultado isolado)
select
  p.protocolo,
  (public.consultar_protocolo_ouvidoria(p.protocolo, 'senha123'))->>'ok'        as senha_certa,
  (public.consultar_protocolo_ouvidoria(p.protocolo, 'senha_errada'))->>'ok'     as senha_errada,
  (public.consultar_protocolo_ouvidoria('OUV-NAOEXISTE', 'x'))->>'ok'            as inexistente
from (
  select (public.criar_denuncia_ouvidoria('sugestao', NULL, 'Teste A4 consulta', 'senha123'))->>'protocolo' as protocolo
) p;

set local role authenticated;
select
  count(*) as linhas_visiveis_para_authenticated_sem_allowlist
from public.ouvidoria_denuncias;

