1	/**
2	 * Canal anônimo de denúncias — página pública, sem login, sem DashboardLayout.
3	 * Duas abas: "Fazer denúncia" e "Acompanhar".
4	 */
5	
6	import { useState, useRef } from 'react';
7	import { useForm } from 'react-hook-form';
8	import { zodResolver } from '@hookform/resolvers/zod';
9	import { z } from 'zod';
10	import { toast } from 'sonner';
11	import { Shield, Lock, Copy, CheckCircle, ChevronRight, Send, Loader2, Eye, EyeOff } from 'lucide-react';
12	import { format, parseISO } from 'date-fns';
13	import { ptBR } from 'date-fns/locale';
14	
15	import { Button } from '@/shared/ui/button';
16	import { Input } from '@/shared/ui/input';
17	import { Label } from '@/shared/ui/label';
18	import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
19	import {
20	  Select,
21	  SelectContent,
22	  SelectItem,
23	  SelectTrigger,
24	  SelectValue,
25	} from '@/shared/ui/select';
26	import { GlassCard } from '@/shared/ui/glass-card';
27	import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
28	
29	import { CATEGORIAS_OUVIDORIA, labelCategoria, labelStatus } from '../lib/categorias';
30	import { LOJAS_OUVIDORIA } from '../lib/lojas';
31	import { useEnviarDenuncia } from '../model/useEnviarDenuncia';
32	import { useConsultarProtocolo } from '../model/useConsultarProtocolo';
33	import { useResponderProtocolo } from '../model/useResponderProtocolo';
34	import { MensagemBubble } from './MensagemBubble';
35	import { CategoriaBadge } from './CategoriaBadge';
36	import { StatusBadge } from './StatusBadge';
37	import type { CategoriaOuvidoria, ConsultaProtocoloResult, MensagemThread } from '../types';
38	
39	// ---------------------------------------------------------------------------
40	// Schema de denúncia
41	// ---------------------------------------------------------------------------
42	
43	const denunciaSchema = z.object({
44	  categoria: z.string({ required_error: 'Selecione uma categoria' }).min(1, 'Selecione uma categoria') as z.ZodType<CategoriaOuvidoria>,
45	  loja_id: z.string().optional(),
46	  mensagem: z
47	    .string({ required_error: 'Escreva sua mensagem' })
48	    .min(10, 'Mínimo de 10 caracteres')
49	    .max(5000, 'Máximo de 5.000 caracteres'),
50	  senha: z.string({ required_error: 'Crie uma senha de acompanhamento' }).min(4, 'Mínimo de 4 caracteres'),
51	  // Honeypot — nunca deve ser preenchido por humanos
52	  hp_field: z.string().optional(),
53	});
54	
55	type DenunciaFormValues = z.infer<typeof denunciaSchema>;
56	
57	// Schema de consulta de protocolo
58	const consultaSchema = z.object({
59	  protocolo: z.string({ required_error: 'Informe o protocolo' }).min(1, 'Informe o protocolo'),
60	  senha: z.string({ required_error: 'Informe a senha' }).min(1, 'Informe a senha'),
61	});
62	
63	type ConsultaFormValues = z.infer<typeof consultaSchema>;
64	
65	// ---------------------------------------------------------------------------
66	// Sub-componente: Formulário de denúncia
67	// ---------------------------------------------------------------------------
68	
69	interface FormDenunciaProps {
70	  onSuccess: (protocolo: string) => void;
71	  onAcompanhar: (protocolo: string) => void;
72	}
73	
74	function FormDenuncia({ onSuccess, onAcompanhar }: FormDenunciaProps) {
75	  const [protocolo, setProtocolo] = useState<string | null>(null);
76	  const [copiado, setCopiado] = useState(false);
77	  const [mostrarSenha, setMostrarSenha] = useState(false);
78	  const enviarDenuncia = useEnviarDenuncia();
79	
80	  const {
81	    register,
82	    handleSubmit,
83	    watch,
84	    setValue,
85	    formState: { errors },
86	    reset,
87	  } = useForm<DenunciaFormValues>({
88	    resolver: zodResolver(denunciaSchema),
89	    defaultValues: { hp_field: '' },
90	  });
91	
92	  const mensagemValue = watch('mensagem') ?? '';
93	
94	  const onSubmit = handleSubmit(async (values) => {
95	    // Honeypot: se preenchido, fingir sucesso sem enviar
96	    if (values.hp_field) {
97	      setProtocolo('XXX-FAKE-0000');
98	      return;
99	    }
100	
101	    try {
102	      const lojaId = values.loja_id && values.loja_id !== '__nao_informar'
103	        ? parseInt(values.loja_id, 10)
104	        : null;
105	
106	      const proto = await enviarDenuncia.mutateAsync({
107	        categoria: values.categoria,
108	        loja_id: lojaId,
109	        mensagem: values.mensagem,
110	        senha: values.senha,
111	      });
112	
113	      setProtocolo(proto);
114	      onSuccess(proto);
115	      reset();
116	    } catch (err) {
117	      toast.error((err as Error).message ?? 'Erro ao registrar denúncia');
118	    }
119	  });
120	
121	  const copiarProtocolo = async () => {
122	    if (!protocolo) return;
123	    try {
124	      await navigator.clipboard.writeText(protocolo);
125	      setCopiado(true);
126	      setTimeout(() => setCopiado(false), 2000);
127	    } catch {
128	      toast.error('Não foi possível copiar. Anote manualmente.');
129	    }
130	  };
131	
132	  if (protocolo) {
133	    return (
134	      <div className="flex flex-col gap-6">
135	        {/* Sucesso */}
136	        <div className="flex flex-col items-center gap-4 py-6">
137	          <div className="rounded-full bg-emerald-50 dark:bg-emerald-900/20 p-4">
138	            <CheckCircle className="h-8 w-8 text-emerald-600" />
139	          </div>
140	          <div className="text-center">
141	            <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
142	              Denúncia registrada
143	            </p>
144	            <p className="text-sm text-muted-foreground mt-1">
145	              Seu protocolo de acompanhamento é:
146	            </p>
147	          </div>
148	          <div className="flex items-center gap-3">
149	            <span className="font-mono text-2xl font-bold text-[#57715B] tracking-widest">
150	              {protocolo}
151	            </span>
152	            <button
153	              type="button"
154	              onClick={copiarProtocolo}
155	              className="rounded-xl p-2 hover:bg-[#57715B]/10 text-[#57715B] transition-colors"
156	              aria-label="Copiar protocolo"
157	            >
158	              {copiado ? <CheckCircle className="h-5 w-5 text-emerald-600" /> : <Copy className="h-5 w-5" />}
159	            </button>
160	          </div>
161	        </div>
162	
163	        {/* Callout de atenção */}
164	        <div className="rounded-2xl border border-amber-200 dark:border-amber-800/30 bg-amber-50 dark:bg-amber-900/10 p-4 flex gap-3">
165	          <Shield className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
166	          <div className="text-sm text-amber-700 dark:text-amber-400">
167	            <p className="font-semibold mb-1">Guarde o protocolo e a senha</p>
168	            <p>
169	              Esses dados são a <strong>única forma</strong> de acompanhar sua denúncia.
170	              Não há recuperação de senha. Recomendamos anotar em local seguro.
171	            </p>
172	          </div>
173	        </div>
174	
175	        {/* Ação: acompanhar */}
176	        <Button
177	          type="button"
178	          onClick={() => onAcompanhar(protocolo)}
179	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
180	        >
181	          Acompanhar denúncia
182	          <ChevronRight className="h-4 w-4" />
183	        </Button>
184	      </div>
185	    );
186	  }
187	
188	  return (
189	    <form onSubmit={onSubmit} className="flex flex-col gap-5">
190	      {/* Callout de anonimato */}
191	      <div className="rounded-2xl border border-[#57715B]/20 bg-[#57715B]/5 p-4 flex gap-3">
192	        <Lock className="h-5 w-5 text-[#57715B] flex-shrink-0 mt-0.5" />
193	        <p className="text-sm text-[#57715B] dark:text-[#8FAE94]">
194	          Sua identidade é protegida. Não registramos quem você é, seu IP ou se está logado.
195	          Evite incluir informações que possam te identificar na mensagem.
196	        </p>
197	      </div>
198	
199	      {/* Honeypot — sr-only, nunca visto por humanos */}
200	      <div className="sr-only" aria-hidden="true">
201	        <input
202	          tabIndex={-1}
203	          autoComplete="off"
204	          {...register('hp_field')}
205	        />
206	      </div>
207	
208	      {/* Categoria */}
209	      <div className="flex flex-col gap-1.5">
210	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
211	          Categoria <span className="text-red-500">*</span>
212	        </Label>
213	        <Select
214	          onValueChange={(v) => setValue('categoria', v as CategoriaOuvidoria, { shouldValidate: true })}
215	        >
216	          <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
217	            <SelectValue placeholder="Selecione uma categoria" />
218	          </SelectTrigger>
219	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
220	            {CATEGORIAS_OUVIDORIA.map((cat) => (
221	              <SelectItem key={cat.value} value={cat.value}>
222	                {cat.label}
223	              </SelectItem>
224	            ))}
225	          </SelectContent>
226	        </Select>
227	        {errors.categoria && (
228	          <p className="text-xs text-red-500">{errors.categoria.message}</p>
229	        )}
230	      </div>
231	
232	      {/* Loja (opcional) */}
233	      <div className="flex flex-col gap-1.5">
234	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
235	          Loja relacionada <span className="text-muted-foreground font-normal">(opcional)</span>
236	        </Label>
237	        <Select onValueChange={(v) => setValue('loja_id', v)}>
238	          <SelectTrigger className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
239	            <SelectValue placeholder="Prefiro não informar" />
240	          </SelectTrigger>
241	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
242	            <SelectItem value="__nao_informar">Prefiro não informar</SelectItem>
243	            {LOJAS_OUVIDORIA.map((loja) => (
244	              <SelectItem key={loja.id} value={String(loja.id)}>
245	                {loja.nome}
246	              </SelectItem>
247	            ))}
248	          </SelectContent>
249	        </Select>
250	      </div>
251	
252	      {/* Mensagem */}
253	      <div className="flex flex-col gap-1.5">
254	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
255	          Mensagem <span className="text-red-500">*</span>
256	        </Label>
257	        <textarea
258	          {...register('mensagem')}
259	          rows={6}
