-- Hardening pós-review: REPLICA IDENTITY, policy own-row em ouvidoria_acesso, bcrypt cost 10.

-- A) Realtime: REPLICA IDENTITY FULL para o filtro RLS aplicar em UPDATE/DELETE
ALTER TABLE public.ouvidoria_mensagens REPLICA IDENTITY FULL;

-- C) ouvidoria_acesso: SELECT restrito à própria linha (não enumera as outras donas)
DROP POLICY IF EXISTS ouvidoria_acesso_select_donas ON public.ouvidoria_acesso;
CREATE POLICY ouvidoria_acesso_select_donas
  ON public.ouvidoria_acesso
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

-- B) bcrypt cost fixado em 10 (CREATE OR REPLACE preserva GRANTs/REVOKEs existentes)
CREATE OR REPLACE FUNCTION public.criar_denuncia_ouvidoria(
  p_categoria text, p_loja_id integer, p_mensagem text, p_senha text
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_categorias_validas text[] := ARRAY['assedio_moral','assedio_sexual','fraude_financeiro','discriminacao','seguranca_trabalho','conduta_etica','sugestao','outro'];
  v_protocolo  text;
  v_senha_hash text;
  i integer;
BEGIN
  IF p_categoria IS NULL OR NOT (p_categoria = ANY(v_categorias_validas)) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Categoria inválida.');
  END IF;
  IF p_mensagem IS NULL OR length(trim(p_mensagem)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem não pode ser vazia.');
  END IF;
  IF length(p_mensagem) > 5000 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem excede 5000 caracteres.');
  END IF;
  IF p_senha IS NULL OR length(p_senha) < 4 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Senha deve ter pelo menos 4 caracteres.');
  END IF;
  v_protocolo := NULL;
  FOR i IN 1..10 LOOP
    v_protocolo := 'OUV-' || upper(encode(extensions.gen_random_bytes(5), 'hex'));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.ouvidoria_denuncias WHERE protocolo = v_protocolo);
    v_protocolo := NULL;
  END LOOP;
  IF v_protocolo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Não foi possível gerar protocolo único. Tente novamente.');
  END IF;
  v_senha_hash := extensions.crypt(p_senha, extensions.gen_salt('bf', 10));
  INSERT INTO public.ouvidoria_denuncias (protocolo, senha_hash, categoria, loja_id, mensagem)
  VALUES (v_protocolo, v_senha_hash, p_categoria, p_loja_id, trim(p_mensagem));
  RETURN jsonb_build_object('ok', true, 'protocolo', v_protocolo);
END;
$$;

CREATE OR REPLACE FUNCTION public.consultar_protocolo_ouvidoria(p_protocolo text, p_senha text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_rec record;
  v_senha_ok boolean;
  v_mensagens jsonb;
BEGIN
  SELECT id, protocolo, senha_hash, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em
  INTO v_rec FROM public.ouvidoria_denuncias WHERE protocolo = p_protocolo;
  IF NOT FOUND THEN
    PERFORM extensions.crypt(p_senha, extensions.gen_salt('bf', 10));
    RETURN jsonb_build_object('ok', false);
  END IF;
  v_senha_ok := (extensions.crypt(p_senha, v_rec.senha_hash) = v_rec.senha_hash);
  IF NOT v_senha_ok THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('autor', m.autor, 'mensagem', m.mensagem, 'created_at', m.created_at) ORDER BY m.created_at), '[]'::jsonb)
  INTO v_mensagens FROM public.ouvidoria_mensagens m WHERE m.denuncia_id = v_rec.id;
  RETURN jsonb_build_object(
    'ok', true,
    'denuncia', jsonb_build_object(
      'protocolo', v_rec.protocolo, 'categoria', v_rec.categoria, 'loja_id', v_rec.loja_id,
      'mensagem', v_rec.mensagem, 'status', v_rec.status, 'created_at', v_rec.created_at,
      'updated_at', v_rec.updated_at, 'ultima_resposta_em', v_rec.ultima_resposta_em),
    'mensagens', v_mensagens);
END;
$$;

CREATE OR REPLACE FUNCTION public.responder_protocolo_ouvidoria(p_protocolo text, p_senha text, p_mensagem text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_rec record;
  v_senha_ok boolean;
BEGIN
  IF p_mensagem IS NULL OR length(trim(p_mensagem)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem não pode ser vazia.');
  END IF;
  IF length(p_mensagem) > 5000 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Mensagem excede 5000 caracteres.');
  END IF;
  SELECT id, senha_hash INTO v_rec FROM public.ouvidoria_denuncias WHERE protocolo = p_protocolo;
  IF NOT FOUND THEN
    PERFORM extensions.crypt(p_senha, extensions.gen_salt('bf', 10));
    RETURN jsonb_build_object('ok', false);
  END IF;
  v_senha_ok := (extensions.crypt(p_senha, v_rec.senha_hash) = v_rec.senha_hash);
  IF NOT v_senha_ok THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  INSERT INTO public.ouvidoria_mensagens (denuncia_id, autor, mensagem, lida_pela_ouvidoria)
  VALUES (v_rec.id, 'denunciante', trim(p_mensagem), false);
  UPDATE public.ouvidoria_denuncias SET updated_at = now() WHERE id = v_rec.id;
  RETURN jsonb_build_object('ok', true);
END;
$$;

